      "informacoes": [
        {
          "citacao": "D25, data em que o protótipo fica disponível",
          "motivo": "valor_divergente",
          "correto_seria": "O protótipo fica disponível em D26."
        },
        {
          "citacao": "até a validação em D35",
          "motivo": "valor_divergente",
          "correto_seria": "A validação é concluída em D36."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "ACTION_LOG.A05",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "A mudança de prazo faz a parcela de gestão e instalação ultrapassar D40; a taxa de R$ 300 por dia excedente continua correta, mas a aplicação do custo deve ser considerada."
    },
    {
      "trecho_id": "ACTION_LOG.A06",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "A entrega do motor mudou para D21, fora da janela de frete indicada. A janela para as peças que chegam entre D16 e D20 continua descritivamente correta, mas a necessidade de incluir o motor requer decisão humana."
    },
    {
      "trecho_id": "RISK_REGISTER.R01",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "não tem folga",
          "motivo": "valor_divergente",
          "correto_seria": "O redutor tem 1 dia de folga: a montagem está prevista para D21 e a entrega do redutor continua em D20."
        },
        {
          "citacao": "qualquer atraso empurraria a montagem para depois de D20 e a liberação para depois de D40",
          "motivo": "premissa_alterada",
          "correto_seria": "Um atraso do redutor de 1 dia, até D21, não deslocaria a montagem nem a liberação; atrasos maiores que 1 dia deslocariam ambas."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R02",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "Uma entrega depois de D20 deslocaria a montagem e, com ela, levaria a validação para depois de D35.",
          "motivo": "premissa_alterada",
          "correto_seria": "Uma entrega da placa e do chicote em D21 não deslocaria a montagem; uma entrega após D21 deslocaria a montagem e levaria a validação para depois de D36."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R03",
      "rotulo": "DECISAO_HUMANA",
      "informacoes": [],
      "observacao": "O teste de vida e seus custos marginais continuam descritos corretamente. A validação prevista mudou para D36, o que afeta o contexto deste risco."
    },
    {
      "trecho_id": "RISK_REGISTER.R04",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "como compras e fabricação não têm folga, cada dia de reanálise adiaria a liberação",
          "motivo": "premissa_alterada",
          "correto_seria": "Compras e fabricação têm 1 dia de folga em relação à montagem prevista para D21; uma reanálise que acrescente 1 dia não adiaria a liberação, mas atrasos maiores poderiam adiá-la."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R05",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "ele terminaria em D31",
          "motivo": "valor_divergente",
          "correto_seria": "Com a repetição integral, o ensaio de vedação terminaria em D32."
        },
        {
          "citacao": "ainda antes da validação em D35",
          "motivo": "valor_divergente",
          "correto_seria": "A validação está prevista para D36; o ensaio repetido ainda terminaria antes dela."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "RISK_REGISTER.R06",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "depois de D20, a montagem começaria depois da data planejada",
          "motivo": "premissa_alterada",
          "correto_seria": "A montagem planejada é em D21; disponibilidade do acoplamento em D21 não a atrasaria. Só disponibilidade após D21 deslocaria a montagem."
        }
      ],
      "observacao": ""
    },
